    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "हर्तुर्याति न गोचरं किमपि शं पुष्णाति यत्सर्वदा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "ह्यर्थिभ्यः प्रतिपाद्यमानमनिशं प्राप्नोति[१] वृद्धिं पराम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "कल्पान्तेष्वपि न प्रयाति निधनं विद्याख्यमन्तर्धनं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "येषां तान्प्रति मानमुज्झत नृपाः कस्तैः सह स्पर्धते ॥ १६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "यद्विद्याख्यमन्तर्धनं हर्तुः चौरस्य गोचरं न याति प्रसिद्धधनवन्नयनविषयं न",
          "end": "space"
        },
        {
          "n": 2,
          "text": "भवति । यत्सर्वदा किमपि अनिर्वाच्यं शं कल्याणं पुष्णाति तनुते । न त्वितरवद्",
          "end": "space"
        },
        {
          "n": 3,
          "text": "आये दुःखं व्यये दुःखमिति दुःखाय भवति । अर्थिभ्योनिशं । न तु काले काले ।",
          "end": "space"
        },
        {
          "n": 4,
          "text": "प्रतिपाद्यमानं दीयमानं परामुत्कृष्टां वृद्धिं प्राप्नोति । नत्वितरवत् क्षयम् । यत्क-",
          "end": "hyphen"
        },
        {
          "n": 5,
          "text": "ल्पान्तेपि निधनं नाशं न प्रयाति । एतादृग् विद्याधनं येषां तान् प्रति मानमहङ्कारं",
          "end": "space"
        },
        {
          "n": 6,
          "text": "त्यजत । कः तैः सह स्पर्धते । न कोपीत्यर्थः । अत्रोपमानात्प्रसिद्धधनादुपमेयस्य",
          "end": "space"
        },
        {
          "n": 7,
          "text": "विद्याधनस्याधिक्यप्रतिपादनाद्व्यतिरेकालङ्कारः । वृत्तं पूर्वोक्तम् ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अधुना उक्तमेवविशदीकुर्वन्नाह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अधिगतपरमार्थान्पण्डितान्मावमंस्था-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "स्तृणमिव लघुलक्ष्मीर्नैव तान्संरुणद्धि ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "अभिनवमदलेखाश्यामगण्डस्थलानां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "न भवति[२] बिसतन्तुर्वारणं वारणानाम् ॥ १७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "हे नृप । परमश्चासौ अर्थश्च परमार्थः तत्वार्थः । अधिगतः परमार्थो यैस्तान्",
          "end": "space"
        },
        {
          "n": 2,
          "text": "पण्डितान् विदुषः मावमंस्थाः । मावमानय । यतः लघु निःसारं तृणमिव लक्ष्मी-",
          "end": "hyphen"
        },
        {
          "n": 3,
          "text": "स्तान्नैव संरुणद्धि । रोद्धुं न शक्नोति । यद्वा लघुश्चासौ लक्ष्मीश्च लघुलक्ष्मीरिति",
          "end": "space"
        },
        {
          "n": 4,
          "text": "समस्तं पदम् । विज्ञातमहातत्वा विद्वांसो लक्ष्मीं तृणमिव गणयन्तीत्यर्थः ।",
          "end": "space"
        },
        {
          "n": 5,
          "text": "अभिनवो यो मदो दानं तस्य लेखा तया श्यामानि गण्डस्थलानि येषां तेषां",
          "end": "space"
        },
        {
          "n": 6,
          "text": "वारणानां बिसतन्तुर्वारणं निरोधको न भवति । मालिनी वृत्तम् ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "ब्रह्मापि विदग्धवैदग्ध्यकीर्त्यपहरणेऽसमर्थः का कथेतरेषामिति दृष्टान्तमुखेनाह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अम्भोजिनीवननिवासविलासमेव[३]",
          "end": "line"
        },
        {
          "n": 2,
          "text": "हंसस्य हन्ति नितरां कुपितो विधाता ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "न त्वस्य दुग्धजलभेदविधौ प्रसिद्धां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "वैदग्ध्यकीर्तिमपहर्तुमसौ समर्थः ॥ १८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r10",
      "type": "footnote",
      "lines": [
